// Orders, visits, kitchen and guest ordering.
// Owner: Agent B1 (see docs/architecture/MODULE_CONTRACTS.md). Other agents
// import from here but do not edit this file.
import { z } from 'zod';
import { isoDate, isoDateTime, optionalText, phoneE164, uuid } from './common';
import { guestPhone } from './phone';
import { ORDER_STATUSES } from './state-machines';

export const ordersContractsVersion = 2 as const;

export const ORDER_CHANNELS = ['qr', 'web', 'whatsapp', 'staff', 'pos', 'mcp', 'phone'] as const;
export const FULFILLMENTS = ['dine_in', 'pickup', 'delivery'] as const;
export const KITCHEN_STATUSES = ['queued', 'preparing', 'ready', 'served', 'cancelled'] as const;
/** Orders the kitchen display shows. */
export const KITCHEN_ACTIVE_STATUSES = ['placed', 'accepted', 'preparing', 'ready'] as const;

/** Visit timing rules preserved from legacy server.js. */
export const VISIT_RULES = {
  autoOpenUndoMs: 60_000,
  autoCloseQuietMs: 10 * 60_000,
} as const;

export const cartLine = z.object({
  productId: uuid,
  quantity: z.number().int().min(1).max(99),
  modifiers: z.array(z.object({ groupId: uuid, optionId: uuid })).max(40).default([]),
  notes: optionalText(200),
});
export type CartLine = z.infer<typeof cartLine>;
const lines = z.array(cartLine).min(1).max(60);

export const guestQuoteRequest = z.object({ lines, promotionCode: optionalText(40) });
export const guestOrderRequest = z.object({
  lines,
  notes: optionalText(500),
  promotionCode: optionalText(40),
  /** The total the guest saw; a different server total is a 409 `price_changed`. */
  expectedTotalMinor: z.number().int().min(0).optional(),
});
export type GuestOrderRequest = z.infer<typeof guestOrderRequest>;
export const serviceRequestInput = z.object({ kind: z.enum(['waiter', 'bill']) });

const deliveryAddress = z.object({
  line1: z.string().trim().min(3).max(300),
  area: optionalText(120),
  city: optionalText(80),
  notes: optionalText(300),
  latitude: z.number().min(-90).max(90).nullable().optional(),
  longitude: z.number().min(-180).max(180).nullable().optional(),
});

export const webQuoteRequest = z.object({
  branchId: uuid,
  fulfillment: z.enum(['pickup', 'delivery']),
  lines,
  promotionCode: optionalText(40),
});
export const webOrderRequest = webQuoteRequest.extend({
  customer: z.object({
    name: z.string().trim().min(1).max(100),
    /** As typed (local EG/SA forms, Arabic-Indic digits); the API stores E.164 for the restaurant's country (CR-06). */
    phone: guestPhone,
    email: z.email().max(200).optional().nullable(),
    marketingConsent: z.boolean().default(false),
  }),
  deliveryAddress: deliveryAddress.optional().nullable(),
  notes: optionalText(500),
  scheduledFor: isoDateTime.optional().nullable(),
  /** pay_at_pickup (pickup) and cod (delivery) create `placed` orders; online uses ResutoPay checkout. */
  payment: z.enum(['pay_at_pickup', 'cod', 'online']),
  expectedTotalMinor: z.number().int().min(0).optional(),
  attribution: z.record(z.string().max(40), z.string().max(300)).optional(),
  returnUrl: z.url().max(500).optional(),
});
export type WebOrderRequest = z.infer<typeof webOrderRequest>;

export const staffOrderRequest = z.object({
  branchId: uuid,
  fulfillment: z.enum(FULFILLMENTS),
  tableId: uuid.optional().nullable(),
  visitId: uuid.optional().nullable(),
  lines,
  customer: z.object({
    name: optionalText(100),
    phone: phoneE164.optional().nullable(),
    email: z.email().max(200).optional().nullable(),
  }).optional().nullable(),
  deliveryAddress: deliveryAddress.optional().nullable(),
  notes: optionalText(500),
  promotionCode: optionalText(40),
  channel: z.enum(['staff', 'phone']).default('staff'),
});
export type StaffOrderRequest = z.infer<typeof staffOrderRequest>;

export const orderTransitionRequest = z.object({
  to: z.enum(ORDER_STATUSES).exclude(['cancelled', 'awaiting_payment']),
  version: z.number().int().min(0).optional(),
});
export const orderCancelRequest = z.object({
  reason: z.string().trim().min(2).max(300),
  version: z.number().int().min(0).optional(),
});
export const COLLECT_METHODS = ['cash', 'card', 'instapay', 'cod'] as const;
export const collectPaymentRequest = z.object({
  /** Defaults to everything still due (after any reservation deposit credit). */
  amountMinor: z.number().int().positive().optional(),
  method: z.enum(COLLECT_METHODS).default('cash'),
  reference: optionalText(120),
});

export const orderListQuery = z.object({
  branchId: uuid.optional(),
  status: z.string().max(200).optional(),          // comma separated
  channel: z.string().max(100).optional(),         // comma separated
  fulfillment: z.enum(FULFILLMENTS).optional(),
  date: isoDate.optional(),                        // business date
  from: isoDateTime.optional(),
  to: isoDateTime.optional(),
  visitId: uuid.optional(),
  q: z.string().trim().max(60).optional(),         // order number
  limit: z.coerce.number().int().min(1).max(200).default(50),
  cursor: z.string().max(200).optional(),
});
export type OrderListQuery = z.infer<typeof orderListQuery>;

// Visits
export const seatVisitRequest = z.object({
  tableId: uuid,
  partySize: z.number().int().min(1).max(100).optional(),
  reservationId: uuid.optional(),
});
export const closeVisitRequest = z.object({
  /** Managers only: close although money is still due or orders are open (audited). */
  force: z.boolean().optional(),
  reason: optionalText(300),
  /** Leave the table in `cleaning` until staff mark it clean. */
  needsCleaning: z.boolean().optional(),
});

// Kitchen
export const kitchenBumpRequest = z.object({
  to: z.enum(['accepted', 'preparing', 'ready', 'served', 'picked_up', 'delivered']),
  version: z.number().int().min(0).optional(),
});
export const kitchenLineRequest = z.object({
  /** queued|preparing|ready. Moving a ready line back (recall) is line-level only. */
  status: z.enum(['queued', 'preparing', 'ready']),
});

// ---------------------------------------------------------------------------
// Response shapes
// ---------------------------------------------------------------------------
export interface OrderLineView {
  id: string; productId: string | null; name: string; nameAr: string | null; quantity: number; unitPriceMinor: number;
  modifiers: Array<{ groupId?: string; group: string; optionId?: string; option: string; optionAr?: string | null; priceDeltaMinor: number }>;
  modifiersTotalMinor: number; lineTotalMinor: number; station: string; kitchenStatus: string; notes: string | null;
}
export interface OrderSummary {
  id: string; number: string; publicRef: string; branchId: string; channel: string; fulfillment: string; status: string;
  paymentStatus: string; tableId: string | null; tableLabel: string | null; visitId: string | null; customerName: string | null;
  currency: string; totalMinor: number; paidMinor: number; refundedMinor: number; dueMinor: number; itemCount: number;
  placedAt: string; businessDate: string; version: number;
}
export interface OrderDetail extends OrderSummary {
  customerId: string | null; customerPhone: string | null; deliveryAddress: unknown; notes: string | null;
  subtotalMinor: number; discountMinor: number; deliveryFeeMinor: number; serviceChargeMinor: number; taxMinor: number; taxInclusive: boolean;
  acceptedAt: string | null; readyAt: string | null; fulfilledAt: string | null; cancelledAt: string | null; cancelReason: string | null;
  scheduledFor: string | null;
  lines: OrderLineView[];
  events: Array<{ id: number; type: string; from: string | null; to: string | null; actorType: string; at: string; details: unknown }>;
  payments: Array<{ id: string; method: string; provider: string; status: string; amountMinor: number; refundedMinor: number; isTest: boolean; createdAt: string }>;
  allocations: Array<{ paymentId: string; amountMinor: number; kind: string; createdAt: string }>;
}

export interface GuestSession {
  token: string; visitId: string; orgId: string; branchId: string; tableLabel: string; currency: 'EGP' | 'SAR';
  org: { name: string; nameAr: string | null; slug: string };
  /** true when this scan opened the table (staff can undo within 60 s). */
  opened: boolean;
}
export interface GuestVisitView {
  visitId: string; status: 'open' | 'closed'; table: { id: string; label: string }; branchId: string; currency: string;
  orders: Array<{ id: string; number: string; status: string; totalMinor: number; placedAt: string; lines: Array<{ name: string; nameAr: string | null; quantity: number; lineTotalMinor: number; kitchenStatus: string; modifiers: string[] }> }>;
  totals: { totalMinor: number; paidMinor: number; creditMinor: number; dueMinor: number };
  requests: Array<{ kind: string; status: string; createdAt: string }>;
  settling: boolean;
}

export interface KitchenTicket {
  id: string; number: string; status: string; fulfillment: string; channel: string; tableLabel: string | null; customerName: string | null;
  placedAt: string; acceptedAt: string | null; ageSeconds: number; notes: string | null; version: number; isNew: boolean;
  lines: Array<{ id: string; name: string; nameAr: string | null; quantity: number; station: string; kitchenStatus: string; notes: string | null; modifiers: string[]; prepMinutes: number | null }>;
}
export interface KitchenFeed { cursor: string; serverTime: string; unchanged?: boolean; stations: string[]; tickets: KitchenTicket[] }
